        if (std::getenv("GTI_TRACE_EXEC") && owner == 3) std::fprintf(stderr, "[extpath] inst=%llu input=%s prefix=%zu\n", (unsigned long long)instruction.id, describeCompleteBorrowFact(input).c_str(), *path->externalPrefix); // TEMP-TRACE
        if (!input)
          continue;
